<?php
namespace App\Filament\Admin\Resources\Claims\Pages;use App\Application\Claims\ClaimLifecycleService;use App\Filament\Admin\Concerns\ServiceValidation;use App\Filament\Admin\Resources\Claims\ClaimResource;use App\Models\User;use Filament\Actions\Action;use Filament\Forms\Components\{Select,TextInput,Textarea};use Filament\Resources\Pages\ViewRecord;
final class ViewClaim extends ViewRecord{protected static string$resource=ClaimResource::class;protected function getHeaderActions():array{return[Action::make('assign')->icon('heroicon-o-user-plus')->schema([Select::make('assignee_id')->options(User::where('status','ACTIVE')->pluck('full_name','id'))->searchable()->required(),TextInput::make('reason_code')->required()->maxLength(64)])->action(function(array$d){if(ServiceValidation::run(fn()=>app(ClaimLifecycleService::class)->assign($this->record,User::findOrFail($d['assignee_id']),$d['reason_code'],auth()->user()))===null)return;}),Action::make('reserve')->icon('heroicon-o-banknotes')->schema([TextInput::make('amount_minor')->numeric()->minValue(0)->required(),TextInput::make('reason_code')->required(),Textarea::make('notes')])->action(function(array$d){if(ServiceValidation::run(fn()=>app(ClaimLifecycleService::class)->requestReserve($this->record,(int)$d['amount_minor'],$d['reason_code'],$d['notes']??null,auth()->user()))===null)return;}),Action::make('advance')->icon('heroicon-o-arrow-right-circle')->schema([Select::make('to_status')->options(['ACKNOWLEDGED'=>'Acknowledge','EVIDENCE_PENDING'=>'Evidence pending','ASSESSMENT'=>'Assessment','CARRIER_REVIEW'=>'Carrier review','CLOSED'=>'Close','REOPENED'=>'Reopen'])->required()->native(false),TextInput::make('reason_code')->required(),Textarea::make('details')])->action(function(array$d){if(ServiceValidation::run(fn()=>app(ClaimLifecycleService::class)->transition($this->record,$d['to_status'],$d['reason_code'],['closure_summary'=>$d['details']??null],auth()->user()))===null)return;})];}}
